29		var in struct {
30			URL    string   `json:"url"`
31			Events []string `json:"events"`
32		}
33		if !decode(w, r, &in) {
34			return
35		}
36		if err := s.hooks.CheckURL(r.Context(), in.URL); err != nil {
37			s.hookError(w, err)
