41			s.hookError(w, err)
42			return
43		}
44		ep, err := s.store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: p.OrgID, URL: in.URL, Events: in.Events, Secret: webhooks.NewSecret(), Enabled: true}, s.clock.Now())
45		if err != nil {
46			s.storeError(w, err)
47			return
48		}
49		writeJSON(w, http.StatusCreated, ep)
50	}
